    this.pose = { ...BASE };
  }

  resetMatch() {
    this.wins = 0;
    this.meter = 20;
    this.resetRound();
  }

  get attackData() {
    return this.attack ? ATTACKS[this.attack.type] : null;
  }

  canAttack() {
    return !this.attack && this.stun <= 0 && !this.ko && !this.victory;
  }

  hurtbox() {
    const h = this.crouching && this.onGround ? 100 : 148;
    return { x: this.x - 27, y: this.y - h, w: 54, h };
  }

  hitbox() {
    if (!this.attack) return null;
    const d = this.attackData;
    if (!d || !d.box) return null;
    const t = this.attack.t;
    if (t <= d.startup || t > d.startup + d.active) return null;
    const b = d.box;
    const x = this.facing === 1 ? this.x + b.x : this.x - b.x - b.w;
    return { x, y: this.y + b.y, w: b.w, h: b.h };
  }

  startAttack(type, game) {
    const d = ATTACKS[type];
    if (!d) return;
    if (d.cost && this.meter < d.cost) {
      game?.flashMeter?.(this);
      return;
    }
    if (type === "fireball" || type === "super") {
      if (!this.onGround) return;
    }
    if (!this.onGround && this.airAttackUsed) return;

    if (d.cost) this.meter = Math.max(0, this.meter - d.cost);
    this.attack = { type, t: 0, hasHit: false, hits: 0, facing: this.facing };
    this.lastAttackType = type;
    this.walking = 0;
    this.airAttackUsed = !this.onGround ? true : this.airAttackUsed;
    this.facing = this.other.x >= this.x ? 1 : -1;

    if (type === "super") {
      game?.onSuperStart?.(this);
    } else if (type === "fireball") {
      game?.onSpecialStart?.(this);
    } else {
      game?.onWhiff?.(this, d);
      game?.sfx?.whiff();
    }
  }

  update(dt, intent, game) {
    this.time += dt;
    const opp = this.other;

    if (this.hurtFlash > 0) this.hurtFlash--;
    if (this.comboTimer > 0) {
      this.comboTimer--;
      if (this.comboTimer === 0) this.combo = 0;
    }
    if (!this.ko && this.stun <= 0) {
      this.meter = Math.min(100, this.meter + 0.028);
    }

    if (this.ko) {
      this.updateKO(dt);
      return;
    }

    if (this.stun > 0) {
      this.stun--;
      this.vx *= 0.92;
      this.physicsStep(dt, game);
      if (this.stun === 0) {
        this.stunType = null;
        this.blocking = false;
      }
      this.updatePose(dt, opp);
      return;
    }

    if (this.victory) {
      this.vx *= 0.8;
      this.physicsStep(dt, game);
      this.updatePose(dt, opp);
      return;
    }

    if (this.attack) {
      this.advanceAttack(game);
      this.vx *= 0.86;
      this.physicsStep(dt, game);
      this.updatePose(dt, opp);
      return;
    }

    this.crouching = false;
    this.blocking = false;

    // Face the opponent while free.
    if (this.onGround) this.facing = opp.x >= this.x ? 1 : -1;

    const backKey = this.facing === 1 ? intent.left : intent.right;
    const fwdKey = this.facing === 1 ? intent.right : intent.left;

    // Guard: holding away while grounded, not attacking.
    if (this.onGround && backKey && !intent.down) this.blocking = true;
    if (this.onGround && backKey && intent.down) {
      this.blocking = true;
      this.crouching = true;
    }

    // Attacks have priority over movement.
    if (intent.superPressed && this.meter >= 100 && this.onGround) {
      this.startAttack("super", game);
      this.updatePose(dt, opp);
      return;
    }
    if (intent.specialPressed && this.meter >= 25 && this.onGround) {
      this.startAttack("fireball", game);
      this.updatePose(dt, opp);
      return;
    }
    if (intent.heavyPressed && (this.onGround || !this.airAttackUsed)) {
      this.startAttack("heavy", game);
      this.updatePose(dt, opp);
      if (this.onGround) this.vx = this.facing * 90;
      return;
    }
    if (intent.lightPressed && (this.onGround || !this.airAttackUsed)) {
      this.startAttack("light", game);
      this.updatePose(dt, opp);
      if (this.onGround) this.vx = this.facing * 60;
      return;
    }

    if (this.onGround) {
      if (intent.down) {
        this.crouching = true;
        this.vx *= 0.6;
      } else {
        if (intent.upPressed) {
          this.vy = -870;
          this.onGround = false;
          this.airAttackUsed = false;
          const dir = (intent.right ? 1 : 0) - (intent.left ? 1 : 0);
          this.vx = dir * 250;
          this.blocking = false;
          this.crouching = false;
          game?.sfx?.jump();
          game?.onJump?.(this);
        } else {
          const dir = (intent.right ? 1 : 0) - (intent.left ? 1 : 0);
          if (dir !== 0) {
            const spd = dir === -this.facing ? this.walkSpeed * 0.84 : this.walkSpeed;
            this.vx = dir * spd;
            this.walking = 1;
            this.walkPhase += dt * (dir === -this.facing ? 9 : 11);
          } else {
            this.vx *= 0.55;
            this.walking = 0;
          }
        }
      }
    } else {
      // gentle air drift
      const dir = (intent.right ? 1 : 0) - (intent.left ? 1 : 0);
      if (dir !== 0) this.vx += dir * 240 * dt;
      this.vx = clamp(this.vx, -360, 360);
    }

    if (!this.onGround) this.crouching = false;

    this.vx = clamp(this.vx, -560, 560);
    this.physicsStep(dt, game);
    this.updatePose(dt, opp);
  }

  advanceAttack(game) {
    const a = this.attack;
    const d = ATTACKS[a.type];
    a.t++;

    if (a.type === "fireball" && a.t === d.startup) {
      game.spawnProjectile(this);
    }

    if (a.type === "super") {
      if (a.t <= d.startup + 26) {
        this.vx = this.facing * 560;
      } else {
        this.vx *= 0.82;
      }
      if (a.t === d.startup) {
        game.flashScreen(0.55, this.palette.glow);
      }
    }

    if (a.t >= d.startup + (d.active || 0) + d.recovery) {
      this.attack = null;
      this.vx *= 0.5;
    }
  }

  physicsStep(dt, game) {
    if (!this.onGround) {
      this.vy += GRAVITY * dt;
      this.y += this.vy * dt;
      if (this.y >= GROUND_Y) {
        this.y = GROUND_Y;
        this.vy = 0;
        if (!this.onGround) {
          this.onGround = true;
          this.airAttackUsed = false;
          game?.onLand?.(this);
        }
      } else {
        this.onGround = false;
      }
    }
    this.x += this.vx * dt;
    if (this.x < STAGE_L) { this.x = STAGE_L; this.vx = 0; }
    if (this.x > STAGE_R) { this.x = STAGE_R; this.vx = 0; }

    // ground friction when idle
    if (this.onGround && !this.attack && this.stun <= 0) {
      this.vx *= 0.7;
      if (Math.abs(this.vx) < 2) this.vx = 0;
    }
  }

  updateKO(dt) {
    const wasAir = !this.onGround;
    this.vy += GRAVITY * dt;
    this.y += this.vy * dt;
    this.x += this.vx * dt;
    this.vx *= 0.985;
    this.x = clamp(this.x, STAGE_L, STAGE_R);
    if (this.y >= GROUND_Y) {
      this.y = GROUND_Y;
      if (this.vy > 60 && wasAir) this.game?.onLand?.(this, true);
      this.vy = 0;
      this.onGround = true;
    }
    const target = -1.34;
    this.koRot += (target - this.koRot) * 0.09;
  }

  takeHit(dmg, dir, d, game, opts = {}) {
    const wasStunned = this.stun > 0 || this.attack !== null;
    const finalDmg = Math.round(dmg * (opts.counter ? 1.18 : 1));
    this.health = Math.max(0, this.health - finalDmg);
    this.hurtFlash = 9;
    this.meter = Math.min(100, this.meter + 8);
    this.attack = null;
    this.stun = d.hitstun + (opts.counter ? 6 : 0);
    this.stunType = "hit";
    this.blocking = false;
    this.crouching = false;
    this.vx = dir * d.kb;
    this.vy = d.launch ? d.launch * (this.onGround ? 1 : 1.2) : this.vy;
    if (d.launch) {
      this.y -= 2;
      this.onGround = false;
    }
    this.facing = dir > 0 ? -1 : 1;
    this.counter = wasStunned && opts.counter;
    if (this.health <= 0) this.knockOut(dir);
    return { wasStunned, finalDmg };
  }

  takeBlock(chipDmg, dir, d, game) {
    const dmg = Math.max(1, Math.round(chipDmg));
    this.health = Math.max(0, this.health - dmg);
    this.meter = Math.min(100, this.meter + 5);
    this.stun = Math.max(8, Math.round((d.hitstun || 14) * 0.55));
    this.stunType = "block";
    this.blocking = true;
    this.vx = dir * 120;
    this.hurtFlash = 3;
    if (this.health <= 0) this.knockOut(dir);
  }

  knockOut(dir) {
    if (this.ko) return;
    this.ko = true;
    this.attack = null;
    this.stun = 0;
    this.victory = false;
    this.vy = -430;
    this.vx = dir * 300;
    this.onGround = false;
    this.koRot = 0;
    this.health = 0;
    this.game?.onKO?.(this);
  }

  setVictory() {
    this.victory = true;
    this.attack = null;
    this.crouching = false;
    this.blocking = false;
  }

  targetPose(opp) {
    const t = this.time;
    const breathe = Math.sin(t * 2.6);

    if (this.stun > 0) {
      if (this.stunType === "block") {
        const p = { ...GUARD };
        p.fhx += Math.sin(this.stun * 0.8) * 2;
        return p;
      }
      const p = { ...HIT };
      p.hdx += breathe * 1.5;
      return p;
    }

    if (this.attack) {
      const a = this.attack;
      const d = this.attackData;
      const type = a.type;
      if (type === "light") {
        const wind = ATTACK_POSES.punchWindup;
        const strike = ATTACK_POSES.punchStrike;
        if (a.t <= d.startup) return blend(BASE, wind, clamp(a.t / d.startup, 0, 1));
        if (a.t <= d.startup + d.active + 3) {
          const k = clamp((a.t - d.startup) / Math.max(1, d.active * 0.6), 0, 1);
          return blend(wind, strike, k);
        }
        const r = clamp((a.t - d.startup - d.active - 3) / Math.max(1, d.recovery - 4), 0, 1);
        return blend(strike, BASE, r);
      }
      if (type === "heavy") {
        const wind = ATTACK_POSES.kickWindup;
        const strike = ATTACK_POSES.kickStrike;
        if (a.t <= d.startup) return blend(BASE, wind, clamp(a.t / d.startup, 0, 1));
        if (a.t <= d.startup + d.active + 6) {
          const k = clamp((a.t - d.startup) / Math.max(1, d.active * 0.5), 0, 1);
          return blend(wind, strike, k);
        }
        const r = clamp((a.t - d.startup - d.active - 6) / Math.max(1, d.recovery - 7), 0, 1);
        return blend(strike, BASE, r);
      }
      if (type === "fireball") {
        const wind = ATTACK_POSES.charge;
        const rel = ATTACK_POSES.release;
        if (a.t <= d.startup) return blend(BASE, wind, clamp(a.t / d.startup, 0, 1));
        if (a.t <= d.startup + 8) return blend(wind, rel, clamp((a.t - d.startup) / 8, 0, 1));
        return blend(rel, BASE, clamp((a.t - d.startup - 8) / d.recovery, 0, 1));
      }
      if (type === "super") {
        const wind = ATTACK_POSES.charge;
        const rel = ATTACK_POSES.rush;
        if (a.t <= d.startup) return blend(BASE, wind, clamp(a.t / d.startup, 0, 1));
        if (a.t <= d.startup + 30) return rel;
        return blend(rel, BASE, clamp((a.t - d.startup - 30) / (d.active + d.recovery - 30), 0, 1));
      }
    }

    if (this.victory) {
      const p = { ...VICTORY };
      const bounce = Math.max(0, Math.sin(t * 5));
      p.hy -= bounce * 8;
      p.sy -= bounce * 8;
      p.hdy -= bounce * 8;
      p.fhy -= bounce * 10;
      p.fhx += Math.sin(t * 5) * 4;
      return p;
    }

    if (!this.onGround) {
      const p = { ...JUMP };
      const k = clamp((this.vy + 900) / 1800, 0, 1);
      p.ffy += k * 8;
      p.bfy += k * 12;
      p.fkx += k * 6;
      p.fhx += Math.sin(t * 8) * 4;
      return p;
    }

    if (this.crouching) {
      const p = { ...CROUCH };
      p.hy += breathe * 0.8;
      p.sy += breathe * 0.8;
      p.hdy += breathe * 0.8;
      return p;
    }

    const moving = Math.abs(this.vx) > 20 && this.stun <= 0 && !this.attack;
    if (moving) {
      const swing = Math.sin(this.walkPhase);
      const p = { ...BASE };
      p.ffx = 22 + swing * 24;
      p.fkx = 18 + swing * 18;
      p.ffy = -Math.max(0, swing) * 14;
      p.fky = -46 + Math.max(0, swing) * 6;
      p.bfx = -24 - swing * 24;
      p.bkx = -18 - swing * 18;
      p.bfy = -Math.max(0, -swing) * 14;
      p.bky = -46 + Math.max(0, -swing) * 6;
      p.fhx = 20 - swing * 12;
      p.fhy = -96 - Math.abs(swing) * 2;
      p.bhx = -10 + swing * 12;
      p.hy = -82 + Math.abs(swing) * 3;
      p.sy = -130 + Math.abs(swing) * 3;
      p.hdy = -156 + Math.abs(swing) * 3;
      return p;
    }

    if (this.blocking) {
      const p = { ...GUARD };
      p.hy += breathe * 0.7;
      p.sy += breathe * 0.7;
      p.hdy += breathe * 0.7;
      return p;
    }

    const p = { ...BASE };
    p.hy += breathe * 1.1;
    p.sy += breathe * 1.4;
    p.hdy += breathe * 1.4;
    p.fhx += breathe * 0.8;
    p.bhx -= breathe * 0.8;
    p.fhy += breathe * 0.7;
    p.bhy += breathe * 0.7;
    p.lean += breathe * 0.004;
    return p;
  }

  updatePose(dt, opp) {
    const target = this.targetPose(opp);
    const baseRate = this.attack ? 0.62 : 0.3;
    const k = 1 - Math.pow(1 - baseRate, Math.min(3, dt * 60));
    for (const key of POSE_KEYS) {
      this.pose[key] += (target[key] - this.pose[key]) * k;
    }
  }

  /** Draw only shadow; the full fighter is drawn by the renderer. */
  drawShadow(ctx) {
    const airborne = !this.onGround;
    const w = this.ko ? 64 : 44;
    const alpha = airborne ? 0.18 : 0.34;
    const g = ctx.createRadialGradient(this.x, GROUND_Y + 2, 2, this.x, GROUND_Y + 2, w);
    g.addColorStop(0, `rgba(0,0,0,${alpha})`);
    g.addColorStop(1, "rgba(0,0,0,0)");
    ctx.save();
    ctx.translate(this.x, GROUND_Y + 2);
    ctx.scale(1, 0.24);
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(0, 0, w, 0, TAU);
    ctx.fill();
    ctx.restore();
  }
}

import { rand, TAU, clamp } from "./utils.js";

export class Fx {
  constructor() {
    this.particles = [];
    this.rings = [];
    this.texts = [];
    this.slashes = [];
    this.maxParticles = 220;
  }

  clear() {
    this.particles.length = 0;
    this.rings.length = 0;
    this.texts.length = 0;
    this.slashes.length = 0;
  }

  spawnHit(x, y, power, color, dir = 1, opts = {}) {
    const n = power === "heavy" || power === "super" ? 18 : 10;
    const speed = power === "heavy" ? 620 : 380;
    for (let i = 0; i < n; i++) {
      const a = rand(-0.9, 0.9) + (dir > 0 ? 0 : Math.PI);
      const v = rand(0.3, 1) * speed;
      this.particles.push({
        x, y,
        vx: Math.cos(a) * v + dir * 40,
        vy: Math.sin(a) * v * 0.8 - rand(0, 120),
        life: rand(0.18, 0.4),
        maxLife: 0.4,
        size: rand(2, 6),
        color,
        type: i % 3 === 0 ? "shard" : "spark",
        gravity: 900,
        drag: 0.94,
        rot: rand(0, TAU),
        spin: rand(-16, 16),
      });
    }
    // bright core streaks
    for (let i = 0; i < 5; i++) {
      const a = rand(-0.5, 0.5) + (dir > 0 ? 0 : Math.PI);
      const v = rand(300, 760);
      this.particles.push({
        x, y,
        vx: Math.cos(a) * v,
        vy: Math.sin(a) * v,
        life: rand(0.12, 0.22),
        maxLife: 0.22,
        size: rand(9, 18),
        color: opts.core || "#fff4d8",
        type: "streak",
        gravity: 0,
        drag: 0.9,
        rot: 0,
        spin: 0,
      });
    }
    this.rings.push({
      x, y, r: 6, vr: power === "heavy" ? 900 : 620,
      life: 0.28, maxLife: 0.28, color, width: power === "heavy" ? 7 : 4,
    });
    if (power === "super") {
      this.rings.push({ x, y, r: 24, vr: 1200, life: 0.45, maxLife: 0.45, color: "#fff2c8", width: 10 });
      this.spawnShock(x, y, color);
    }
  }

  spawnBlock(x, y, color) {
    for (let i = 0; i < 10; i++) {
      const a = rand(0, TAU);
      const v = rand(90, 320);
      this.particles.push({
        x, y,
        vx: Math.cos(a) * v,
        vy: Math.sin(a) * v - 60,
        life: rand(0.15, 0.3),
        maxLife: 0.3,
        size: rand(2, 4),
        color,
        type: "spark",
        gravity: 300,
        drag: 0.93,
        rot: 0,
        spin: 0,
      });
    }
    this.rings.push({ x, y, r: 10, vr: 420, life: 0.22, maxLife: 0.22, color, width: 3 });
  }

  spawnShock(x, y, color) {
    this.rings.push({ x, y, r: 16, vr: 520, life: 0.6, maxLife: 0.6, color, width: 5 });
    this.rings.push({ x, y, r: 4, vr: 260, life: 0.8, maxLife: 0.8, color: "#fff0d8", width: 2 });
  }

  spawnDust(x, y, n = 6, dir = 0, color = "rgba(220,190,170,0.5)") {
    for (let i = 0; i < n; i++) {
      const a = -Math.PI / 2 + rand(-0.9, 0.9);
      const v = rand(30, 140);
      this.particles.push({
        x: x + rand(-16, 16), y: y - 4,
        vx: Math.cos(a) * v + dir * 60,
        vy: Math.sin(a) * v * 0.5,
        life: rand(0.3, 0.6),
        maxLife: 0.6,
        size: rand(6, 14),
        color,
        type: "dust",
        gravity: -30,
        drag: 0.92,
        rot: 0,
        spin: 0,
      });
    }
  }

  spawnTrail(x, y, color, size = 5, vy = 0) {
    this.particles.push({
      x, y,
      vx: rand(-24, 24),
      vy: vy + rand(-18, 18),
      life: rand(0.2, 0.4),
      maxLife: 0.4,
      size,
      color,
      type: "ember",
      gravity: -40,
      drag: 0.95,
      rot: 0,
      spin: 0,
    });
  }

  spawnFireBurst(x, y, color, n = 20) {
    for (let i = 0; i < n; i++) {
      const a = rand(0, TAU);
      const v = rand(60, 360);
      this.particles.push({
        x, y,
        vx: Math.cos(a) * v,
        vy: Math.sin(a) * v,
        life: rand(0.25, 0.6),
        maxLife: 0.6,
        size: rand(5, 15),
        color,
        type: "orb",
        gravity: -60,
        drag: 0.92,
        rot: 0,
        spin: 0,
      });
    }
    this.rings.push({ x, y, r: 10, vr: 600, life: 0.4, maxLife: 0.4, color, width: 6 });
  }

  spawnText(x, y, text, color = "#fff", size = 26) {
    this.texts.push({ x, y, text, color, size, life: 0.8, maxLife: 0.8, vy: -46 });
  }

  update(dt) {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.life <= 0) {
        this.particles.splice(i, 1);
        continue;
      }
      p.vy += p.gravity * dt;
      p.vx *= Math.pow(p.drag, dt * 60);
      p.vy *= Math.pow(p.drag, dt * 60);
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.rot += p.spin * dt;
    }
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i];
      r.life -= dt;
      if (r.life <= 0) {
        this.rings.splice(i, 1);
        continue;
      }
      r.r += r.vr * dt;
      r.vr *= 0.9;
    }
    for (let i = this.texts.length - 1; i >= 0; i--) {
      const t = this.texts[i];
      t.life -= dt;
      if (t.life <= 0) {
        this.texts.splice(i, 1);
        continue;
      }
      t.y += t.vy * dt;
      t.vy *= 0.92;
    }
    for (let i = this.slashes.length - 1; i >= 0; i--) {
      const s = this.slashes[i];
      s.life -= dt;
      if (s.life <= 0) this.slashes.splice(i, 1);
    }
    if (this.particles.length > this.maxParticles) {
      this.particles.splice(0, this.particles.length - this.maxParticles);
    }
  }

  draw(ctx) {
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (const p of this.particles) {
      const k = clamp(p.life / p.maxLife, 0, 1);
      ctx.globalAlpha = k;
      if (p.type === "streak") {
        ctx.strokeStyle = p.color;
        ctx.lineWidth = p.size * 0.4;
        ctx.lineCap = "round";
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(p.x - p.vx * 0.028, p.y - p.vy * 0.028);
        ctx.stroke();
      } else if (p.type === "shard") {
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot);
        ctx.fillStyle = p.color;
        ctx.fillRect(-p.size, -p.size * 0.35, p.size * 2 * k + 2, p.size * 0.7);
        ctx.restore();
      } else if (p.type === "dust") {
        ctx.globalAlpha = k * 0.4;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * (1.6 - k * 0.6), 0, TAU);
        ctx.fill();
      } else {
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, Math.max(0.5, p.size * k), 0, TAU);
        ctx.fill();
      }
    }
    for (const r of this.rings) {
      const k = clamp(r.life / r.maxLife, 0, 1);
      ctx.globalAlpha = k * 0.9;
      ctx.strokeStyle = r.color;
      ctx.lineWidth = r.width * k + 0.5;
      ctx.beginPath();
      ctx.arc(r.x, r.y, r.r, 0, TAU);
      ctx.stroke();
    }
    ctx.restore();

    for (const t of this.texts) {
      const k = clamp(t.life / t.maxLife, 0, 1);
      const pop = 1 + (1 - k) * 0.15;
      ctx.save();
      ctx.globalAlpha = Math.min(1, k * 2);
      ctx.translate(t.x, t.y);
      ctx.scale(pop, pop);
      ctx.font = `900 ${t.size}px Vazirmatn, sans-serif`;
      ctx.textAlign = "center";
      ctx.lineWidth = 4;
      ctx.strokeStyle = "rgba(10,5,15,0.75)";
      ctx.strokeText(t.text, 0, 0);
      ctx.fillStyle = t.color;
      ctx.fillText(t.text, 0, 0);
      ctx.restore();
    }
  }
}

content.text:
Now game.js. This handles fighters, projectiles, rounds, CPU, announcements, HUD data.

Palettes:
```
const PALETTES = {
  0: {name:'آتش', latin:'ATASH', primary:'#ff5a36', secondary:'#ffb15c', dark:'#4a1024', trim:'#ffd27a', hair:'#1c1220', skin:'#f2b48c', glow:'#ff7a45', energy:'#ff7a45', eyes:'#ffd9a8'},
  1: {name:'یخ', latin:'YAKH', primary:'#3cc9f5', secondary:'#9c8bff', dark:'#0d2b48', trim:'#c9f6ff', hair:'#eaf9ff', skin:'#e6c3ae', glow:'#68e6ff', energy:'#5be7ff', eyes:'#bff8ff'}
}
```
Fighter palettes need style details (hairStyle, scarf, coat).

Game:
```
export const W=1280,H=720;
class Game {
 constructor(canvas, sfx, input)
 state='menu'
 mode='pvp'
 time=0
 hitstop=0
 shakeX/shakeY/shakeMag
 flash={a:0,color}
 announcement=null
 round=1, timer=75, timerStart=75
 projectiles=[]
 particles fx
 cameraZoom
 slow
 onMatchEnd callback
 fighters [...]
 cpu = {timer, action...}
 winner
 resultShown
 trainDummy? no
}
```

Menu state: fighters idle; positions maybe 380/900. Fighters update with empty intents. Hide HUD in render by state.

startMatch(mode):
- reset match scores/meter; round=1; state='intro'; introTimer=0; announcement...
- position fighters; set `matchWinner=null`; hide results via callback.

Round reset:
```
resetRound(){
 f.resetRound(); projectiles=[]; fx.clear(); timer=75; 
 this.roundIntro = 0; this.state='intro'; this.announcedFight=false;
 this.announce('آماده','READY',...,1.4)
}
```
Need intro sequence using `this.stateTime`:
- state 'intro': stateTime += dt; if !fightAnnounced && stateTime>0.9 → announce 'مبارزه!' FIGHT, sfx.fight, fightAnnounced=true; state='fight'? If state changes to fight immediately at 0.9, then inputs active while announcement still showing — good.
- Announce at start of intro 'آماده'.

Start match via menu: state intro, stateTime 0; announce آماده.
Round transitions: after roundEnd timer 2.6 → if wins>=2 show matchEnd overlay else next intro.

Announce API:
```
announce(text, sub, color, duration=1.2, size=96){ this.announcement={text,sub,color,t:0,dur:duration,size}; }
```
Render alpha/scale based on t.

Timer: during fight only; decrement by dt. When <=0 → timeUp.

Hit resolution:
For each fighter f with attack:
- d = attackData.
- if type 'super': hit window between startup and startup+active; use multi-hit: allow next hit when `t - attack.lastHitT >= interval`, hits<max. Need target hit that frame. On each hit, set attack.lastHitT = t, hits++. It shouldn't set hasHit.
- normal: window and !hasHit.

Check overlap(hitbox, target.hurtbox). If target.ko skip.

On hit:
- determine counter: target.attack && target.attack.t <= target.attackData.startup + target.attackData.active (i.e., in startup/active) or target.stun? Counter if target is attacking. 
- if target.blocking && target.onGround && !target.ko && (target.stun<=0? yes) → block. Block direction: target holding away, true. Determine if attack is low? skip.
- Normal hit:
  - damage scaling by attacker.combo.
  - hitstop = d.hitstop (global max).
  - target.takeHit(dmg, dir, d, this, {counter});
  - attacker.combo = (target.stun > 0 before? ) Actually compute before applying: comboActive = target.stun > 0 && target.stunType==='hit'. attacker.combo = comboActive ? attacker.combo+1 : 1; attacker.comboTimer = 90;
  - attacker.meter += d.meterGain (cap).
  - fx.spawnHit at contact point.
  - shake, freeze; flash heavy.
  - sfx[d.sfx].
  - floating text for counter "ضربه متقابل!".
  - if health<=0 → already knockOut triggered; game handles round end via onKO callback.
- Block:
  - chip = d.damage * d.chip (or super 0.05).
  - target.takeBlock(chip, dir, d, this)
  - fx.spawnBlock
  - sfx.block
  - small hitstop 3
  - attacker.meter += 4
  - floating text "دفاع" perhaps small.
- Super hits also produce bigger fx and freeze.

Also whiff sound is played startAttack for normals. Fine.

Projectiles:
```
spawnProjectile(f){
  const p = {x: f.x + f.facing*58, y: f.y-108, vx: f.facing*640, owner:f.id, color: f.palette.glow, life:2.4, r:24, trail:[], anim:0}
  this.projectiles.push(p); sfx.fireball(); fx...
}
updateProjectiles(dt):
  for each: x += vx*dt; life -= dt; anim += dt; trail circles;
  check collision with opponent hurtbox (circle vs rect) → if blocking: chip 8 damage, block stun 10, destroy; else damage 72, hitstun 22, kb 260; destroy.
  collide with other projectile → both destroy + burst.
  out of stage bounds → destroy.
```
Projectile hits also grant attacker meter.

Hit freeze: during game.hitstop>0 skip updates except fx/camera/time. So update order in game.update:

```
update(dt){
 time += dt;
 // fx always
 this.fx.update(dt);
 this.updateCamera(dt);
 if (state==='menu'){ update menu fighters idle; return; }
 if (state==='paused') return; // main loop may still animate? maybe freeze
 if (hitstop>0){ hitstop-=1; return; }
 ...
}
```
Time-based announcements use game time; if hitstop stops times, announcement freezes too (fine). Use `animTime` incrementing always for visuals.

State handling:
- intro: stateTime += dt, update fighters with empty intents (they idle), check fight start. Fighters face each other.
- fight: timer decrement, update inputs/fighters/projectiles, resolve collisions, push, combo timers, check KO (done callback), time up.
- roundEnd: stateTime += dt; fighters update with empty intent (KO physics & victory animation continues), projectiles cleared; after duration → nextRound or matchEnd.
- matchEnd: fighters idle/victory; no updates? Keep updating victory pose.
- menu: idle fighters update with empty intents; not HUD; camera normal.

Round end triggered by onKO callback:
```
onKO(loser){
 if (state!=='fight') return;
 winner = other;
 this.state='roundEnd'; stateTime=0; roundEndDuration=2.7;
 winner.wins++;
 winner.setVictory();
 this.announce('ناک اوت','K.O.', winner.palette.color, 2.2, 108);
 this.sfx.ko(); this.flashScreen(0.8,'#fff'); shake;
 this.slowmo=0.5? skip
 this.roundWinner = winner;
}
```
Need note winner.wins++ once.

Time up:
```
if timer<=0: state roundEnd; compare health; if equal draw; else winner.wins++; announce 'زمان تمام' 'TIME UP'; winner.setVictory(); loser stays idle (not ko). 
```
During roundEnd, both fighters idle/victory. Then after delay:
if wins >= 2 → matchEnd; else round++, resetRound.

For match end:
- set state 'matchEnd'; stateTime 0; call ui.onMatchEnd({winner, wins}) after small delay? To show overlay after 1.2s. Simplify: immediately show after 1.4s via game timer; `this.matchEndShown=false; this.matchEndTimer`.
Actually on roundEnd completion when wins>=2:
```
this.state='matchEnd'; this.stateTime=0; this.matchWinner=winner; this.announce(...);
this.onMatchEnd?.(...) after? 
```
Call onMatchEnd immediately; UI overlay appears while fighters celebrate. Acceptable, maybe 0.6s delay using stateTime in update: at 1.2s call once. Do that.

- on rematch: startMatch(mode).
- on menu: state='menu', reset layout, hide HUD etc.

Pause:
- togglePause only if state fight/intro/roundEnd? Pause during fight only (and intro maybe). When paused, store prevState; overlay; resume restore. Keep update skipping.
Implement `pause()` and `resume()`; main UI handles DOM.

Camera shake:
```
addShake(mag){ this.shakeMag = Math.max(this.shakeMag, mag); }
updateCamera(dt){ this.shakeMag *= 0.88; this.shakeX = rand(-1,1)*shakeMag; ... }
```
Render uses translate offsets.

Pushboxes:
```
separate(){
 const [a,b]=fighters; const min=70;
 const dx = b.x-a.x;
 if (Math.abs(dx)<min && a.y... ) { push both away; if one cornered push other more }
}
```
Do when both not ko. If one airborne and other ground still separate horizontally but allow pass? Simpler always separate if |dx|<62 and vertical overlap. With jumps, maybe allow cross-up. We'll separate only if both near ground (|y diff| < 120). 

Also clamp positions.

CPU AI:
intent object fields left,right,up,down,lightPressed,heavyPressed,specialPressed,superPressed,upPressed.
Per frame build intent based on decision timer.
```
updateCPU(dt){
 const ai = this.fighters[1], target=this.fighters[0];
 this.cpu.timer -= dt;
 if dying/ko return empty
 const dist = target.x-ai.x; const adist=Math.abs(dist); const dir=Math.sign(dist);
 // reset presses each frame
 let intent = {left:false,...}
 if (ai.attack || ai.stun>0) return intent;
 if (this.cpu.timer<=0){
   // choose action
   this.cpu.timer = rand(0.18,0.5);
   r=Math.random();
   if (adist>260) { this.cpu.move=dir; ... sometimes fireball if meter }
   else if (adist>120) { approach or jump }
   else { attack }
 }
```
Better: continuous steering + random attack press events.

Implement CPU with internal state `cpu={moveDir:0, timer:0, attackCD:0, jumpCD:0, defend:0}`. Each frame:
- compute dist, dir.
- face opponent automatically.
- if opponent is attacking and close and random guard chance: hold back.
- Movement: if dist > 150 → move forward; if dist < 95 → sometimes back; else occasionally.
- Attack decision every ~0.3-0.7 s: if in range 140, press light/heavy; if meter>=100 and dist<170 press super; if meter>=25 and dist>200 press special; jump occasionally.
- Difficulty medium: reaction delay.

Set intent direction relative to world keys (left/right), not forward. AI is fighter 2; facing toward P1 normally left. Moving toward target: if dist>0 → right.

Blocking for AI: hold away (right if opponent left). Guard chance when opponent attacking: set intent.right true.

Simplest implementation:
```
updateCPU(dt){
 const me=f2, foe=f1; const intent=empty();
 if (me.ko||me.stun>0||me.victory) return intent;
 const dist = foe.x-me.x, ad=Math.abs(dist), dir=Math.sign(dist);
 this.cpu.cd -= dt; this.cpu.moveCd -= dt;
 // guard reaction
 const foeThreat = foe.attack && (foe.attack.t < 20) && ad < 200;
 if (foeThreat && Math.random()<0.06) this.cpu.guard = 0.35;
 if (this.cpu.guard>0){ this.cpu.guard-=dt; if (dist>0) intent.left=true; else intent.right=true; return intent; }
 // attack
 if (ad < 168 && this.cpu.cd<=0 && me.canAttack()) {
   const r=Math.random();
   if (me.meter>=100 && ad<140 && r<0.35) intent.superPressed=true;
   else if (ad<150 && r<0.6) intent.lightPressed=true;
   else if (r<0.85) intent.heavyPressed=true;
   else if (me.meter>=25) intent.specialPressed=true;
   this.cpu.cd = rand(0.22,0.55);
   return intent;
 }
 if (ad>230 && me.meter>=25 && Math.random()<0.01) intent.specialPressed=true;
 // move
 if (ad>125) { if (dist>0) intent.right=true; else intent.left=true; }
 else if (ad<80) { if (dist>0) intent.left=true; else intent.right=true; }
 // occasional jump
 if (ad>140 && ad<320 && Math.random()<0.006) intent.upPressed=true;
 return intent;
}
```
Random guard with per-frame 0.06 is high; use timer-based guard decision when foe starts attack. Add cpu.guardCheck cooldown. Keep simple but not too defensive: set guard 0.25 seconds with probability 0.5 when foe attack starts (detect `foe.attack && foe.attack.t===1`).

Store cpu.lastFoeAttackT to detect new attack.

HUD flashMeter when insufficient: set game.meterFlash for player id, HUD pulses red. Implement `flashMeter(f){ this.meterFlash = {id:f.id, t:0.4}; }`.

onSpecialStart: sfx? fireball sound at spawn.

